INSERT OR REPLACE INTO ec_membership_plans (id, slug, status, created_at, updated_at, published_at, version, locale, translation_group, name, description, price, sale_price, currency, billing_period, features, sort_order) VALUES ('plan_monthly', 'the-thu-vien-hoc-ky', 'published', '2026-10-08T22:43:41.836Z', '2026-10-08T22:43:41.836Z', '2026-10-08T22:43:41.836Z', 1, 'en', 'plan_monthly', 'Thẻ Thư Viện Học Kỳ', 'Đồng hành học tập suốt 1 học kỳ, truy cập toàn bộ kho bài giảng nền tảng và bài tập thế cờ.', 99000, NULL, 'VND', 'học kỳ', '["Toàn quyền học hơn 20+ chuyên đề cờ vua học đường","Thực hành hơn 1.000+ thế cờ tương tác có phân tích","Tài liệu bài tập PDF in ấn bổ trợ kiến thức","Hỏi đáp chuyên môn cùng Hội đồng Sư phạm"]', 1);
INSERT OR REPLACE INTO ec_membership_plans (id, slug, status, created_at, updated_at, published_at, version, locale, translation_group, name, description, price, sale_price, currency, billing_period, features, sort_order) VALUES ('plan_yearly', 'the-thu-vien-nien-hoc', 'published', '2026-10-08T22:43:41.836Z', '2026-10-08T22:43:41.836Z', '2026-10-08T22:43:41.836Z', 1, 'en', 'plan_yearly', 'Thẻ Thư Viện Niên Học (Trọn Năm)', 'Giải pháp đồng hành học tập toàn diện suốt cả năm học dành cho học sinh phổ thông.', 699000, NULL, 'VND', 'năm học', '["Toàn bộ quyền lợi của Thẻ Thư Viện Học Kỳ","Mở khóa toàn bộ chuyên đề Khai cuộc, Chiến thuật & Tàn cuộc","Nhận trọn bộ cẩm nang & sơ đồ tư duy cờ vua học đường PDF","Hỗ trợ phân tích chuyên sâu 2 ván cờ/tháng bởi Kiện tướng","Giấy chứng nhận hoàn thành cấp độ từ Cờ Vua Học Đường"]', 2);
INSERT OR REPLACE INTO ec_membership_plans (id, slug, status, created_at, updated_at, published_at, version, locale, translation_group, name, description, price, sale_price, currency, billing_period, features, sort_order) VALUES ('plan_vip_lifetime', 'the-thu-vien-truong-hoc-clb', 'published', '2026-10-08T22:43:41.836Z', '2026-10-08T22:43:41.836Z', '2026-10-08T22:43:41.836Z', 1, 'en', 'plan_vip_lifetime', 'Thẻ Thư Viện Trường Học & CLB', 'Dành cho Giáo viên Phụ trách & Ban Chủ nhiệm CLB Cờ vua trường học sử dụng giảng dạy tập thể.', 1990000, NULL, 'VND', 'trọn đời', '["Toàn quyền sử dụng kho bài giảng trình chiếu trên lớp học","Chuyển giao trọn bộ giáo án sinh hoạt CLB 36 tuần theo năm học","Tập huấn phương pháp sư phạm 1-1 cho giáo viên phụ trách CLB","Tặng 01 bộ cờ treo tường biểu diễn & cẩm nang sinh hoạt CLB","Cố vấn chuyên môn xuyên suốt quá trình hoạt động của CLB"]', 3);
INSERT OR REPLACE INTO ec_courses (id, slug, status, created_at, updated_at, published_at, version, locale, translation_group, title, excerpt, description, featured_image, category_id, access_level, is_purchasable, price, sale_price, currency, duration_hours, difficulty, featured) VALUES ('course_chess_intro', 'nhap-mon-co-vua-cho-nguoi-moi-bat-dau', 'published', '2026-10-08T22:43:41.836Z', '2026-10-08T22:43:41.836Z', '2026-10-08T22:43:41.836Z', 1, 'en', 'course_chess_intro', 'Nhập Môn Cờ Vua: Làm Quen Bàn Cờ & Tư Duy Nước Đi', 'Khung kiến thức chuẩn hóa từ quy tắc bàn cờ, cách di chuyển quân đến những bài học tư duy không gian trực quan.', 'Chuyên đề được thiết kế sư phạm đặc biệt dành cho học sinh mầm non và tiểu học mới làm quen cờ vua.', 'https://images.unsplash.com/photo-1529699211952-734e80c4d42b?w=800&auto=format&fit=crop&q=80', 'cat_intro', 'free', 1, 149000, NULL, 'VND', 2.5, 'beginner', 1);
INSERT OR REPLACE INTO ec_courses (id, slug, status, created_at, updated_at, published_at, version, locale, translation_group, title, excerpt, description, featured_image, category_id, access_level, is_purchasable, price, sale_price, currency, duration_hours, difficulty, featured) VALUES ('course_chess_tactics', '100-don-chien-thuat-chieu-het-kinh-dien', 'published', '2026-10-08T22:43:41.836Z', '2026-10-08T22:43:41.836Z', '2026-10-08T22:43:41.836Z', 1, 'en', 'course_chess_tactics', '100 Đòn Chiến Thuật & Bài Tập Phối Hợp Mẫu Mực', 'Rèn luyện khả năng quan sát và tính toán nước đi: Đòn bắt đôi, găm quân, giương đông kích tây và phối hợp lực lượng.', 'Chiến thuật là nền tảng rèn luyện khả năng tính toán chính xác và tư duy phản xạ nhanh cho học sinh.', 'https://images.unsplash.com/photo-1586165368502-1bad197a6461?w=800&auto=format&fit=crop&q=80', 'cat_tactics', 'paid', 1, 299000, NULL, 'VND', 4, 'intermediate', 1);
INSERT OR REPLACE INTO ec_courses (id, slug, status, created_at, updated_at, published_at, version, locale, translation_group, title, excerpt, description, featured_image, category_id, access_level, is_purchasable, price, sale_price, currency, duration_hours, difficulty, featured) VALUES ('course_chess_opening_italian', 'bi-quyet-khai-cuoc-italian-va-bay-khai-cuoc', 'published', '2026-10-08T22:43:41.836Z', '2026-10-08T22:43:41.836Z', '2026-10-08T22:43:41.836Z', 1, 'en', 'course_chess_opening_italian', 'Nguyên Lý Khai Cuộc Ý & Phương Pháp Phát Triển Quân Nhanh', 'Làm chủ Khai cuộc Ý (Giuoco Piano), nguyên tắc kiểm soát trung tâm và bảo vệ Vua an toàn.', 'Khai cuộc Ý là hệ thống khai cuộc chuẩn mực và mang tính sư phạm cao nhất cho các bạn học sinh.', 'https://images.unsplash.com/photo-1560174038-da43ac74f01b?w=800&auto=format&fit=crop&q=80', 'cat_opening', 'membership', 1, 349000, NULL, 'VND', 5.5, 'intermediate', 1);
INSERT OR REPLACE INTO ec_courses (id, slug, status, created_at, updated_at, published_at, version, locale, translation_group, title, excerpt, description, featured_image, category_id, access_level, is_purchasable, price, sale_price, currency, duration_hours, difficulty, featured) VALUES ('course_chess_endgame_rook', 'tuyet-ky-co-tan-xe-tot-can-ban-den-chuyen-sau', 'published', '2026-10-08T22:43:41.836Z', '2026-10-08T22:43:41.836Z', '2026-10-08T22:43:41.836Z', 1, 'en', 'course_chess_endgame_rook', 'Nghệ Thuật Cờ Tàn Xe & Tốt: Rèn Luyện Tính Kiên Trì', 'Nắm chắc các thế cờ tàn mẫu mực (Lucena, Philidor), rèn luyện tư duy quy nạp và chuyển hóa ưu thế.', 'Cờ tàn là thước đo chiều sâu tư duy và sự kiên định của học sinh trong từng quyết định.', 'https://images.unsplash.com/photo-1580541832626-2a7131ee809f?w=800&auto=format&fit=crop&q=80', 'cat_endgame', 'paid', 1, 350000, NULL, 'VND', 3.5, 'advanced', 0);

